import {VILLAGES} from './settlements.js';
import * as G from './survival.js';
import {COMMUNITY_REALMS,COMMUNITY_REQUESTS,COMMUNITY_PROJECTS,requestReason,postTravelReason} from './community.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bag=items=>Object.entries(items).map(([id,n])=>G.ITEMS[id].name+' ×'+n).join('、');
const button=(action,id,text,value='',disabled=false)=>`<button class="secondary" data-community="${action}" data-community-id="${esc(id)}" data-value="${esc(value)}" ${disabled?'disabled':''}>${esc(text)}</button>`;
export function requestCard(s,id){
 const e=s.community,stage=e.requests[id],d=COMMUNITY_REQUESTS[id][stage],reason=requestReason(s,id),n=s.nodes.find(n=>n.id==='village-'+id),near=G.inHome(s)&&n&&G.distance(s.player,n)<=155;
 return`<article class="co-card community-request"><small>聚落生活事务 · ${stage}/2</small><h3>${d?d.name:'✓ 一起完成的生活'}</h3><p>${d?d.text:'雨棚、饭篮和工具留下了我们的共同记忆。可以进屋看一看，往后不再重复交材料。'}</p>${d?`<p>交付：${bag(d.cost)}<br>回礼：${bag(d.reward)} · 洞见 +3、好感 +6、安稳 +5</p>${button('request',id,reason||(!near?'先当面交谈':'交付物资，一起完成'),'',!!reason||!near||!G.craftAffordable(s,d.cost))}`:''}<p class="subtle">没有截止日期，不扣另一聚落好感。可以先去冒险。</p></article>`;
}
export function outpostPanel(s,b){
 const e=s.community,near=G.distance(s.player,b)<=180;
 return`<section class="community-post"><h3>这一站，留一点补给</h3><p>储物接入下方库存；搬运机可接驳前哨与货栈。休整每天每图一次，1 旅行口粮＋2 木材 → 生命 +25、饱食 +30、意识 +15、湿冷 −40，不跳过夜晚。</p>${button('rest',b.id,e.rests[s.expedition.current]===G.day(s)?'今日已休整':'吃过行粮，休整片刻','',!near||e.rests[s.expedition.current]===G.day(s)||!G.craftAffordable(s,{ration:1,wood:2}))}<details><summary>前哨往返 · 四级空间折叠</summary><p>需要起终点都有前哨，起终点安全。每次消耗随身 1 原晶＋2 共鸣；未探索的区域不会凭空开放。普通虫洞仍可免费回家。</p><div class="community-travel">${COMMUNITY_REALMS.filter(id=>id!==s.expedition.current).map(id=>{const reason=postTravelReason(s,b.id,id);return`<article><b>${G.REALMS[id].name}</b><small>${esc(reason||'路线可用 · 1 原晶＋2 共鸣')}</small>${button('travel',b.id,'前往'+G.REALMS[id].name,id,!!reason)}</article>`;}).join('')}</div></details>${Object.entries(COMMUNITY_PROJECTS).map(([id,p])=>{const done=e.projects[id].includes(s.expedition.current);return`<details><summary>${p.name} · ${e.projects[id].length}/6</summary><p>${p.text}<br>本地投入：${bag(p.cost)}<br>六地完成回礼：${bag(p.reward)}、洞见 +${p.insight}。</p>${button('project',b.id,done?'✓ 本图已完成':'投入本地物资',id,done||!near||s.level<p.level||id==='beacon'&&e.projects.supply.length<6||!G.craftAffordable(s,p.cost))}</details>`;}).join('')}</section>`;
}
export function communityPanel(s){
 const e=s.community,maps=[[s.expedition.current,s],...Object.entries(s.expedition.worlds)],season=G.season(s),local=s.buildings.find(b=>b.type==='outpost');
 // 资源图鉴依据首次亲手采得记录解锁；说明与战斗教学仍然随时可读。
 const resources=Object.entries(G.NODES).filter(([,d])=>Object.keys(d.drop||{}).length>0&&!['animal','lostpack'].includes(d.type));
 return`<div class="community-hero"><small>4.0 · 荒野共同体</small><h3>机器照料日常，人去遇见远方</h3><p>机器人工作循环 → 聚落生活事务 → 前哨与货栈补给线 → 六地共同的记忆。</p><div class="robot-actions"><button class="primary" data-do="robots">管理三种机器人</button><button class="secondary" data-do="villages">拜访聚落</button><button class="secondary" data-do="odyssey">晶能与跨图货运</button></div></div><details class="community-section" open><summary>六图经营与补给</summary><p>现在是${season.name}，${season.tip}。前哨库存不会远程进背包；机器人只推进当前地图，晶能货栈沿用在线世界运输。</p><div class="community-realms">${COMMUNITY_REALMS.map(id=>{const map=maps.find(([key])=>key===id)?.[1],post=map?.buildings.find(b=>b.type==='outpost'),relay=map?.buildings.find(b=>b.type==='relay');return`<article><small>${id===s.expedition.current?'当前位置':map?'已经到访':'尚未到访'}</small><h3>${G.REALMS[id].name}</h3><p>前哨 ${post?'✓':'—'} · 货栈 ${relay?'✓':'—'}<br>${post?'前哨木材 '+(post.inventory?.wood||0)+' · 口粮 '+(post.inventory?.ration||0):'亲自探索并在当地建设'}<br>补给约定 ${e.projects.supply.includes(id)?'✓':'○'} · 纪念碑 ${e.projects.beacon.includes(id)?'✓':'○'}</p>${post&&id===s.expedition.current?`<button class="secondary" data-inspect-go="${esc(post.id)}">走近并管理前哨</button>`:''}</article>`;}).join('')}</div><div class="robot-actions"><button class="secondary" data-open-category="advanced">前哨站配方</button><button class="secondary" data-open-category="camp">碎石小路配方</button><button class="secondary" data-do="map">地图与资源记忆</button></div>${local?outpostPanel(s,local):'<p>三级掌握共生实践后建前哨，四级空间折叠后可往返；不影响现有虫洞路线。</p>'}</details><details class="community-section"><summary>聚落来信 · 可延期的共同事务</summary><div class="community-requests">${Object.keys(COMMUNITY_REQUESTS).map(id=>`<section><h3>${VILLAGES[id].name}</h3>${requestCard(s,id)}</section>`).join('')}</div></details><details class="community-section"><summary>采集图鉴 · ${resources.filter(([id])=>s.discoveries.includes('node:'+id)).length}/${resources.length} 已发现</summary><p>亲手采得才点亮；机器人收货不替你完成首次认识。未发现的资源不显示产出细节，材料追踪仍可正常帮助你找来源。</p><div class="community-catalog">${resources.map(([id,d])=>{const seen=s.discoveries.includes('node:'+id);return`<article class="${seen?'':'undiscovered'}"><b>${seen?'✓ '+d.name:'? 未发现'}</b><small>${seen?bag(d.drop):'到新的地形亲手采集，留下记录'}</small></article>`;}).join('')}</div></details><details class="community-section"><summary>荒野编年史 · 最近 ${e.log.length} 条</summary><p>第 ${G.day(s)} 天 · 采集 ${s.stats.gathered} 次 · 建造与合成 ${s.stats.crafted} 次 · 跨图 ${s.expedition.crossings} 次 · 园丁运回收成 ${e.gardens} 趟</p><button class="secondary" data-do="community-export">导出本地旅程回顾 JSON</button>${e.log.map(x=>`<p><small>第 ${x.day} 天 · ${G.REALMS[x.realm].name}</small><br>${esc(x.text)}</p>`).join('')||'<p>完成一件共同事务，故事就从这里开始。</p>'}</details>`;
}
